-- Release 49 (3462): the four gaps of the notification and data map (scripts/notification-map.json) are closed.
--   1. owner_late_return (email and portal notice): the owner hears once when their car is 2 hours (late_admin_minutes) past its
--      return time; the return itself is owner_trip_completed (2620).
--   2. Sales: staff_request_open_to_sales (notice and email) with the To do "A booking request is open to Sales" when a website
--      request has no reply after 30 minutes (request_sales_after_minutes, was 15), business hours only (8 am to 9 pm Toronto
--      time, a request that waited overnight is told at 8 am). After 2 hours staff_request_waiting goes to customer service, Sales
--      and the Admins (the Admin escalation).
--   3. Finance: staff_balance_overdue_digest every day from 9 am Toronto time (amounts, days overdue and booking links, only when
--      a balance is overdue) and an Admin To do "Renter balance overdue" per statement unpaid 3 days or more (closes when it is paid).
--      A balance is overdue from the day after its statement was sent.
--   4. Finance and the Admins: staff_refund_issued and staff_refund_failed for every refund that is paid or fails.
-- Everything runs from app.job_r49_notices (pg_cron, every 5 minutes). No applied migration is edited: app.job_requests_open_to_sales
-- is wrapped (_pre3462). The catalogue block is generated by supabase/seed/3462_gen_catalogue.mjs. SCHEMA_MARKER 3462.
set local check_function_bodies = off;

create function pg_temp.copy_grants(p_new regprocedure, p_old regprocedure) returns void
language plpgsql as $$
declare g text;
begin
  execute format('revoke all on function %s from public, anon, authenticated', p_new);
  foreach g in array array['anon', 'authenticated', 'service_role'] loop
    if has_function_privilege(g, p_old, 'execute') then execute format('grant execute on function %s to %I', p_new, g); end if;
  end loop;
end $$;

