-- ================================================================ 2. Sales after 30 minutes
alter table program_settings alter column request_sales_after_minutes set default 30;
update program_settings set request_sales_after_minutes = 30 where request_sales_after_minutes = 15;

create function app.r49_business_hours(p_now timestamptz default now()) returns boolean
language sql stable set search_path = public, app as $$
  select extract(hour from p_now at time zone 'America/Toronto') between 8 and 20
$$;

-- the To do waits for the morning outside business hours
alter function app.job_requests_open_to_sales(timestamptz) rename to job_requests_open_to_sales_pre3462;
create function app.job_requests_open_to_sales(p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = public, app as $$
begin
  if not app.r49_business_hours(p_now) then return 0; end if;
  return app.job_requests_open_to_sales_pre3462(p_now);
end $$;
select pg_temp.copy_grants('app.job_requests_open_to_sales(timestamptz)'::regprocedure, 'app.job_requests_open_to_sales_pre3462(timestamptz)'::regprocedure);

-- ================================================================ 3. the To do
insert into task_rules (task_type, queue, title, priority, due_kind, due_amount, procedure_no, completion_rule, description) values
  ('balance_overdue', 'admin', 'Renter balance overdue: collect it or escalate', 'high', 'none', null, null, null,
   'A renter statement was sent 3 or more days ago and its balance is unpaid (3462). Call the renter, send the pay link again or charge the card on file; it closes by itself when the statement is paid.')
on conflict (task_type) do nothing;

-- ================================================================ the job
create function app.job_r49_notices(p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = public, app as $$
declare
  s program_settings := app.settings(app.local_date(p_now));
  v_today date := app.local_date(p_now);
  v_base text := rtrim(s.notify_base_url, '/');
  b bookings;
  r record;
  v_n integer := 0;
  v_id bigint;
  v_items jsonb;
  v_count integer;
  v_total bigint;
begin
  -- 1. the owner: a car 2 hours late
  for b in select x.* from bookings x
            where x.status = 'on_rent' and app.booking_is_out(x, p_now) and x.booking_type <> 'owner'
              and x.return_at <= p_now - make_interval(mins => s.late_admin_minutes) and x.return_at > p_now - interval '7 days'
  loop
    continue when not app.owner_mail_booking(b) or app.booking_insurer_open_end(b);
    v_id := app.ntf_emit('owner_late_return', 'booking', b.id, 'r' || extract(epoch from b.return_at)::bigint,
      jsonb_build_object('booking_id', b.id, 'owner_id', b.owner_id,
                         'late_by', floor(extract(epoch from (p_now - b.return_at)) / 3600)::integer || ' hours'));
    v_n := v_n + (v_id is not null)::integer;
  end loop;

  -- 2. Sales: a request open to them (the To do is raised by app.job_requests_open_to_sales, every 5 minutes)
  if app.r49_business_hours(p_now) then
    for r in select b2.id, b2.requested_at from bookings b2
              where b2.status = 'requested'
                and exists (select 1 from tasks t where t.booking_id = b2.id and t.task_type = 'request_open_to_sales' and t.status in ('open', 'in_progress', 'waiting'))
    loop
      v_id := app.ntf_emit('staff_request_open_to_sales', 'booking', r.id, 'open',
        jsonb_build_object('booking_id', r.id, 'waiting_time', greatest(floor(extract(epoch from (p_now - coalesce(r.requested_at, p_now))) / 60)::integer, 0) || ' minutes'));
      v_n := v_n + (v_id is not null)::integer;
    end loop;
  end if;

  -- 3. Finance: the overdue balances. The To do closes when the statement is paid.
  update tasks t set status = 'done', completed_at = p_now, completion_note = 'The balance was paid (3462)'
    from booking_statements bs
   where t.task_type = 'balance_overdue' and t.dedupe_key = 'balance_overdue:' || bs.id and t.status in ('open', 'in_progress', 'waiting') and bs.paid_at is not null;
  for r in select bs.id, bs.booking_id, b2.booking_number, b2.vehicle_id, b2.renter_id, rn.legal_name,
                  (bs.charges_cents + bs.hst_cents - bs.deposit_applied_cents - bs.charged_to_card_cents) as due_cents,
                  (v_today - app.local_date(bs.sent_at)) as days_over
             from booking_statements bs join bookings b2 on b2.id = bs.booking_id join renters rn on rn.id = b2.renter_id
            where bs.sent_at is not null and bs.paid_at is null and not b2.is_test
              and bs.charges_cents + bs.hst_cents - bs.deposit_applied_cents - bs.charged_to_card_cents > 0
              and app.local_date(bs.sent_at) <= v_today - 3
  loop
    perform app.raise_task(p_type => 'balance_overdue',
      p_title => format('%s owes %s on booking %s, %s days overdue', r.legal_name, app.fmt_money(r.due_cents), r.booking_number, r.days_over),
      p_detail => 'The statement was sent ' || r.days_over || ' days ago and is still unpaid. Call the renter, send the pay link again or charge the card on file.',
      p_booking => r.booking_id, p_vehicle => r.vehicle_id, p_renter => r.renter_id, p_due_at => p_now, p_dedupe => 'balance_overdue:' || r.id);
  end loop;
  if extract(hour from p_now at time zone 'America/Toronto') >= 9 then
    select coalesce(jsonb_agg(jsonb_build_object('booking_number', x.booking_number, 'amount_due', app.fmt_money(x.due_cents), 'renter_name', x.legal_name,
                                                 'days_overdue', x.days_over::text, 'url', v_base || '/staff/bookings/' || x.booking_number) order by x.days_over desc, x.booking_number),
                    '[]'::jsonb), count(*), coalesce(sum(x.due_cents), 0)
      into v_items, v_count, v_total
      from (select b2.booking_number, rn.legal_name, (bs.charges_cents + bs.hst_cents - bs.deposit_applied_cents - bs.charged_to_card_cents) as due_cents,
                   (v_today - app.local_date(bs.sent_at)) as days_over
              from booking_statements bs join bookings b2 on b2.id = bs.booking_id join renters rn on rn.id = b2.renter_id
             where bs.sent_at is not null and bs.paid_at is null and not b2.is_test
               and bs.charges_cents + bs.hst_cents - bs.deposit_applied_cents - bs.charged_to_card_cents > 0
               and app.local_date(bs.sent_at) < v_today) x;
    if v_count > 0 then
      v_id := app.ntf_emit('staff_balance_overdue_digest', 'balance_digest', null, to_char(v_today, 'YYYY-MM-DD'),
        jsonb_build_object('items', v_items, 'overdue_count', v_count::text, 'overdue_total', app.fmt_money(v_total), 'overdue_date', app.fmt_date(p_now)));
      v_n := v_n + (v_id is not null)::integer;
    end if;
  end if;
  return v_n;
end $$;
revoke all on function app.job_r49_notices(timestamptz), app.r49_business_hours(timestamptz) from public, anon, authenticated;
grant execute on function app.job_r49_notices(timestamptz), app.r49_business_hours(timestamptz) to service_role;

-- ================================================================ 4. refunds paid or failed
create function app.ntf_r49_refunds() returns trigger
language plpgsql security definer set search_path = public, app as $$
begin
  if new.status in ('paid', 'failed') and (tg_op = 'INSERT' or old.status is distinct from new.status) then
    perform app.ntf_emit(case when new.status = 'paid' then 'staff_refund_issued' else 'staff_refund_failed' end, 'refund', new.id, new.status,
      jsonb_build_object('booking_id', new.booking_id, 'refund_amount', app.fmt_money(new.amount_cents),
                         'refund_reason', initcap(replace(new.reason, '_', ' '))));
  end if;
  return null;
end $$;
create trigger refunds_r49_notify after insert or update of status on refunds for each row execute function app.ntf_r49_refunds();

-- ================================================================ the schedule
do $$
begin
  if not exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    raise notice 'pg_cron is not available here: the r49 notices job is not scheduled';
    return;
  end if;
  begin
    create extension if not exists pg_cron;
  exception when others then
    raise warning 'pg_cron could not be created in this database (%): the r49 notices job is not scheduled', sqlerrm;
    return;
  end;
  perform cron.schedule('carmacars-r49-notices', '*/5 * * * *', $q$select app.job_r49_notices()$q$);
end $$;
